insert into public.modules(qualification_id,title,code,description,published,credits,nqf_level,semester,academic_year,official_url)
select i.qualification_id,i.title,i.code,i.description,i.published,i.credits,i.nqf_level,i.semester,i.academic_year,i.official_url
from incoming i
where i.qualification_id is not null
and not exists(select 1 from public.modules m where m.qualification_id=i.qualification_id and m.code=i.code);


